import{createCodexSubscriptionModel}from"./chatgpt/model.js";function experimental_chatgpt(e=`gpt-5.6-sol`){let t=e.trim(),n=t.startsWith(`openai/`)?t.slice(7):t;if(n.length===0)throw Error(`Expected experimental_chatgpt "model" to name an OpenAI model, for example "gpt-5.6-sol".`);if(n.includes(`/`))throw Error(`experimental_chatgpt serves OpenAI models through the local ChatGPT login; received "${e}".`);return createCodexSubscriptionModel({model:n})}export{experimental_chatgpt};